// Diagnostic: with the REAL ContentCatalog loaded, how many trophies does the
// cabinet actually contain, curated (hand-authored) vs auto-generated, and how big
// do the sets get? Informs whether the cabinet should include auto-gen completion
// badges. Boots the systems headlessly (same serving trick as the page harness).
const path = require('path');
const fs = require('fs');
const puppeteer = require('puppeteer');

const APP = path.resolve(__dirname, '../_app');
const PAGE_URL = 'https://hexworth.com/__stats';

(async () => {
    const browser = await puppeteer.launch({ args: ['--no-sandbox', '--disable-setuid-sandbox'] });
    const page = await browser.newPage();
    await page.evaluateOnNewDocument(() => localStorage.setItem('hexworth_house', 'forge'));
    await page.setRequestInterception(true);
    const scripts = ['components/AchievementManager.js', 'components/AchievementSystem.js', 'components/ContentCatalog.js',
        'components/AchievementRegistry.js', 'components/ObservatoryBadges.js', 'components/TrophyCabinet.js'];
    const html = '<!doctype html><html><head><meta charset="utf-8"></head><body>' +
        scripts.map(s => '<script src="/' + s + '"></script>').join('') + '</body></html>';
    // Serve the stub page + the component scripts from disk; block everything else.
    page.on('request', req => {
        const u = req.url();
        if (u === PAGE_URL) { req.respond({ contentType: 'text/html', body: html }); return; }
        const m = u.match(/https:\/\/hexworth\.com\/(components\/.+\.js)$/);
        if (m && fs.existsSync(path.join(APP, m[1]))) { req.respond({ contentType: 'application/javascript', body: fs.readFileSync(path.join(APP, m[1])) }); return; }
        req.respond({ body: '' });
    });
    await page.goto(PAGE_URL, { waitUntil: 'domcontentloaded' });
    await new Promise(r => setTimeout(r, 500));

    const stats = await page.evaluate(() => {
        if (window.AchievementRegistry && AchievementRegistry.init) AchievementRegistry.init();
        var defs = AchievementRegistry.getAllDefinitions();
        var auto = defs.filter(function (d) { return d.autoGenerated; }).length;
        var curated = defs.length - auto;
        // Set sizes WITH auto-gen (current buildModel).
        var withAuto = TrophyCabinet.buildModel().sets.map(function (s) { return s.id + ':' + s.total; });
        // Category breakdown.
        var byCat = {}; defs.forEach(function (d) { byCat[d.category] = (byCat[d.category] || 0) + 1; });
        var catAuto = {}; defs.forEach(function (d) { if (d.autoGenerated) catAuto[d.category] = (catAuto[d.category] || 0) + 1; });
        return { total: defs.length, auto: auto, curated: curated, withAuto: withAuto, byCat: byCat, catAuto: catAuto };
    });
    await browser.close();

    // Report: totals, the biggest sets, and the per-category auto-gen breakdown.
    console.log('\n  Trophy Cabinet — real catalog stats\n');
    console.log('  total definitions: ' + stats.total + '   curated: ' + stats.curated + '   auto-generated: ' + stats.auto);
    console.log('\n  set sizes (current, WITH auto-gen):');
    stats.withAuto.sort(function (a, b) { return (+b.split(':')[1]) - (+a.split(':')[1]); }).forEach(function (s) { console.log('    ' + s); });
    console.log('\n  category breakdown (total / auto-gen):');
    Object.keys(stats.byCat).sort(function (a, b) { return stats.byCat[b] - stats.byCat[a]; }).forEach(function (c) {
        console.log('    ' + c + ': ' + stats.byCat[c] + (stats.catAuto[c] ? '  (' + stats.catAuto[c] + ' auto)' : ''));
    });
    console.log('');
})();
